// Test file: src/app/routes/article/article.mapper.test.ts

import { articleMapper } from './article.mapper';

describe('article.mapper', () => {
  describe('calculateReadingTime', () => {
    // Note: If calculateReadingTime is exported separately, import and test directly
    // Otherwise, test through articleMapper integration

    it('should return 1 for empty body', () => {
      const article = { body: '', slug: 'test', title: 'Test' };
      const result = articleMapper(article);
      expect(result.readingTime).toBe(1);
    });

    it('should return 1 for null body', () => {
      const article = { body: null, slug: 'test', title: 'Test' };
      const result = articleMapper(article);
      expect(result.readingTime).toBe(1);
    });

    it('should return 1 for undefined body', () => {
      const article = { body: undefined, slug: 'test', title: 'Test' };
      const result = articleMapper(article);
      expect(result.readingTime).toBe(1);
    });

    it('should calculate reading time for text with less than 200 words', () => {
      const article = {
        body: 'This is a short article with only fifty words. '.repeat(2), // ~100 words
        slug: 'test',
        title: 'Test'
      };
      const result = articleMapper(article);
      expect(result.readingTime).toBe(1); // Math.ceil(100/200) = 1
    });

    it('should calculate reading time for text with exactly 200 words', () => {
      const article = {
        body: 'word '.repeat(200),
        slug: 'test',
        title: 'Test'
      };
      const result = articleMapper(article);
      expect(result.readingTime).toBe(1); // Math.ceil(200/200) = 1
    });

    it('should calculate reading time for text with more than 200 words', () => {
      const article = {
        body: 'word '.repeat(450), // 450 words
        slug: 'test',
        title: 'Test'
      };
      const result = articleMapper(article);
      expect(result.readingTime).toBe(3); // Math.ceil(450/200) = 3
    });

    it('should strip HTML tags before counting words', () => {
      const article = {
        body: '<p>This is a <strong>test</strong> article with <em>HTML</em> tags.</p><div>More content here.</div>', // ~10 words
        slug: 'test',
        title: 'Test'
      };
      const result = articleMapper(article);
      expect(result.readingTime).toBe(1);
    });

    it('should handle multiple whitespaces correctly', () => {
      const article = {
        body: 'word    word   word     word', // 4 words with extra spaces
        slug: 'test',
        title: 'Test'
      };
      const result = articleMapper(article);
      expect(result.readingTime).toBe(1);
    });

    it('should handle newlines and tabs', () => {
      const article = {
        body: 'word\n\nword\t\tword\r\nword',
        slug: 'test',
        title: 'Test'
      };
      const result = articleMapper(article);
      expect(result.readingTime).toBe(1);
    });

    it('should calculate reading time for large article (1000+ words)', () => {
      const article = {
        body: 'word '.repeat(1000),
        slug: 'test',
        title: 'Test'
      };
      const result = articleMapper(article);
      expect(result.readingTime).toBe(5); // Math.ceil(1000/200) = 5
    });
  });

  describe('articleMapper integration', () => {
    it('should include readingTime in mapped article object', () => {
      const article = {
        slug: 'test-article',
        title: 'Test Article',
        description: 'Test description',
        body: 'word '.repeat(300),
        createdAt: new Date(),
        updatedAt: new Date(),
        favoritesCount: 0
      };

      const result = articleMapper(article);

      expect(result).toHaveProperty('readingTime');
      expect(typeof result.readingTime).toBe('number');
      expect(result.readingTime).toBe(2); // Math.ceil(300/200) = 2
    });

    it('should not mutate the original article object', () => {
      const article = {
        slug: 'test',
        title: 'Test',
        body: 'word '.repeat(100)
      };
      const originalBody = article.body;

      articleMapper(article);

      expect(article.body).toBe(originalBody);
    });
  });
});

